final_files.run_campaign.sh:
#!/bin/bash
# Submit the fit and its dependent summary job without waiting on a login node.
set -euo pipefail

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
fit_job_id=$(sbatch --parsable "$script_dir/fit_catalogue.sh")
fit_job_id=${fit_job_id%%;*}
summary_job_id=$(sbatch --parsable --dependency="afterok:${fit_job_id}" "$script_dir/make_summary.sh")
summary_job_id=${summary_job_id%%;*}

printf 'Submitted fit job %s and dependent summary job %s.\n' "$fit_job_id" "$summary_job_id"
